mapper.select:
SELECT 
  AND p.id IN #{id}
ORDER BY p.resource_id, p.id DESC

SELECT , tv.version_no AS target_version_no
FROM ddc_ai_publication p
JOIN ddc_ai_resource r ON r.tenant_id = p.tenant_id AND r.id = p.resource_id
JOIN ddc_ai_version tv ON tv.tenant_id = p.tenant_id AND tv.resource_id = p.resource_id
    AND tv.id = p.target_version_id AND tv.deleted_at IS NULL
WHERE p.tenant_id = #{tenantId} AND p.deleted_at IS NULL AND r.deleted_at IS NULL
  AND p.resource_id = #{resourceId}
AND p.request_id = #{requestId}
ORDER BY p.id DESC
LIMIT #{limit} OFFSET #{offset}

SELECT count(*) 
  AND p.resource_id = #{resourceId}
AND p.request_id = #{requestId}
